from math import log10

def demo_crossover() -> None:
    for d in range(57, 64):
        lhs = d * 9 ** d
        rhs = 10 ** (d - 1)
        verdict = 'floor wins' if lhs < rhs else 'ceiling wins'
        print(f'd={d}: log10(d*9^d)={log10(lhs):.4f} vs {d-1:.4f} -> {verdict}')
    print('holds for all d in [61,400):', all(d*9**d < 10**(d-1) for d in range(61, 400)))

if __name__ == '__main__':
    demo_crossover()

