function IS_NARCISSISTIC(n):
    ds <- base-ten digits of n          # least significant first
    d  <- length(ds)
    S  <- 0
    for a in ds:
        S <- S + a^d
    return (S == n)

function ALL_NARCISSISTIC(max_len):
    results <- empty set
    for d in 1..max_len:
        for combo in multisets of size d over {0..9}:
            T <- sum(a^d for a in combo)
            if length(digits(T)) == d and multiset(digits(T)) == combo:
                results.add(T)
    return sorted(results)

