function CROSSOVER_HOLDS(d):
    return d * 9^d < 10^(d-1)

function NARCISSISTIC_UPPER_BOUND():
    d <- 1
    while not CROSSOVER_HOLDS(d):
        d <- d + 1
    return 10^(d-1)   # no narcissistic number can have >= d digits

